"""Settings from the environment, with .env as a fallback. Values are never printed or logged."""
import os
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_ENDPOINT = "https://ingest.neatlogs.com"
DEFAULT_PROJECT = "Anurag's project"


def read_env_file(path: Path) -> dict[str, str]:
    out: dict[str, str] = {}
    if not path.is_file():
        return out
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        v = v.strip()
        if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
            v = v[1:-1]
        out[k.strip().removeprefix("export ").strip()] = v
    return out


@dataclass(frozen=True)
class Config:
    target: str | None
    model: str
    neatlogs_endpoint: str
    neatlogs_project: str
    neatlogs_api_key: str | None = field(repr=False)  # repr=False keeps the key out of logs and tracebacks


def load(env_file: Path | None = None) -> Config:
    """The process environment wins over the .env file."""
    env = {**read_env_file(env_file or ROOT / ".env"), **os.environ}
    return Config(
        target=env.get("FENCE_TARGET") or None,
        model=env.get("FENCE_MODEL") or "sonnet",
        neatlogs_endpoint=(env.get("NEATLOGS_ENDPOINT") or DEFAULT_ENDPOINT).rstrip("/"),
        neatlogs_project=env.get("NEATLOGS_PROJECT") or DEFAULT_PROJECT,
        neatlogs_api_key=env.get("NEATLOGS_API_KEY") or None,
    )

"""Fence resolver: issue -> code it names -> blame -> Entire checkpoint -> intent evidence.
Reads only git data (no Entire login, no `entire why`).
usage: python -m fence.resolve <repo> <issues.json> <out.json> [--at-created] [--only=N,N]"""
import collections
import json
import re
import subprocess
import sys
from functools import cached_property
from typing import Any

FileRef = tuple[str, int | None, int | None]  # path, first line, last line
Span = tuple[str, int, int, str]  # file, first line, last line, how it was found

STOP = set("""New Error String Close Open Read Write Run Get Set Load Save Config Client Context Status Start Stop
Init Parse Format Name Type Kind Event Path Hook Hooks Session Sessions Check Fix Apply Is Has Do Len Add Remove main""".split())
PATH_RE = re.compile(r"(?<![\w/.-])((?:[\w.-]+/)*[\w.-]+\.go)(?:(?::|#L)(\d+)(?:[-–](?:L)?(\d+))?)?")
SYM_RE = re.compile(r"`([A-Za-z_][\w.]*)(?:\(\))?`|\b([a-z]+[A-Z]\w{4,}|[A-Z][a-z]+[A-Z]\w{3,})\(")
TRAILER_RE = re.compile(r"^(Co-Authored-By|Entire-|Signed-off-by)")


def refs_from(text: str | None) -> tuple[list[FileRef], list[str]]:
    """Go files (with optional line range) and symbols named in free text."""
    files: list[FileRef] = []
    syms: list[str] = []
    for m in PATH_RE.finditer(text or ""):
        files.append((m.group(1), int(m.group(2)) if m.group(2) else None, int(m.group(3)) if m.group(3) else None))
    for m in SYM_RE.finditer(text or ""):
        s = (m.group(1) or m.group(2)).split(".")[-1]
        if len(s) >= 5 and s not in STOP and re.match(r"^[A-Za-z_]\w*$", s):
            syms.append(s)
    return list(dict.fromkeys(files))[:12], list(dict.fromkeys(syms))[:15]


def strip_trailers(body: str) -> str:
    return "\n".join(l for l in body.splitlines() if not TRAILER_RE.match(l)).strip()


class Repo:
    """Read-only view of a git clone that has the Entire checkpoint refs fetched."""

    def __init__(self, path: str) -> None:
        self.path = path
        self._files: dict[str, list[str]] = {}
        self._ev: dict[tuple[str, str], dict[str, Any]] = {}

    def git(self, *args: str) -> str:
        return subprocess.run(["git", "-C", self.path, *args], capture_output=True, text=True, errors="replace").stdout

    @cached_property
    def commit_checkpoints(self) -> dict[str, list[str]]:
        """commit -> checkpoint ids (from the Entire-Checkpoint trailer)."""
        c2t: dict[str, list[str]] = {}
        for l in self.git("log", "--format=%H %(trailers:key=Entire-Checkpoint,valueonly,separator=%x2C)").splitlines():
            p = l.split()
            c2t[p[0]] = p[1].split(",") if len(p) > 1 else []
        return c2t

    @cached_property
    def ulid_ids(self) -> set[str]:
        return {r.rsplit("/", 1)[1] for r in self.git("for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/").split()}

    @cached_property
    def hex_ids(self) -> set[str]:
        ids: set[str] = set()
        for n in self.git("ls-tree", "-r", "--name-only", "entire/checkpoints/v1").splitlines():
            m = re.match(r"^([0-9a-f]{2})/([0-9a-f]{10})/metadata.json$", n)
            if m:
                ids.add(m.group(1) + m.group(2))
        return ids

    def checkpoint_tree(self, ck: str) -> str | None:
        """Tree-ish prefix for a checkpoint; append a path inside it to address a blob."""
        if ck in self.ulid_ids:
            return f"refs/entire/checkpoints/{ck[-2:]}/{ck}:"
        if ck in self.hex_ids:
            return f"entire/checkpoints/v1:{ck[:2]}/{ck[2:]}/"
        return None

    def checkpoint_files(self, ck: str) -> list[str]:
        t = self.checkpoint_tree(ck)
        if not t:
            return []
        return self.git("ls-tree", "-r", "--name-only", t if t.endswith(":") else t.rstrip("/")).splitlines()

    def checkpoint_blob(self, ck: str, name: str) -> str:
        t = self.checkpoint_tree(ck)
        return self.git("cat-file", "-p", t + name) if t else ""

    def rev_at(self, ts: str) -> str:
        return self.git("rev-list", "-1", f"--before={ts}", "HEAD").strip() or "HEAD"

    def tree_files(self, rev: str) -> list[str]:
        if rev not in self._files:
            self._files[rev] = [f for f in self.git("ls-tree", "-r", "--name-only", rev).splitlines() if f.endswith(".go")]
        return self._files[rev]

    def locate_file(self, rev: str, f: str) -> str | None:
        fs = self.tree_files(rev)
        if f in fs:
            return f
        c = [x for x in fs if x.endswith("/" + f)]
        return c[0] if len(c) == 1 else None

    def func_spans(self, rev: str, sym: str) -> list[tuple[str, int, int]]:
        out = self.git("grep", "-n", "-E", r"^func (\([^)]*\) )?%s[\[(]" % re.escape(sym), rev, "--", "*.go")
        res: list[tuple[str, int, int]] = []
        for l in out.splitlines():
            p = l.split(":", 3)
            if len(p) < 4 or p[1].endswith("_test.go"):
                continue
            f, n = p[1], int(p[2])
            src = self.git("show", f"{rev}:{f}").split("\n")
            e = n
            while e < len(src) and src[e - 1] != "}":
                e += 1
            res.append((f, n, e))
        return res[:3]

    def blame(self, rev: str, f: str, a: int, b: int) -> list[str]:
        out = self.git("blame", "--line-porcelain", "-L", f"{a},{b}", rev, "--", f)
        return [m.group(1) for m in re.finditer(r"^([0-9a-f]{40}) \d+ \d+", out, re.M)]

    def commit_message(self, commit: str) -> tuple[str, str, str]:
        """subject, date, body without trailers."""
        subj, date, body = (self.git("log", "-1", "--format=%s%x00%as%x00%b", commit).split("\x00") + ["", "", ""])[:3]
        return subj, date, strip_trailers(body)

    def evidence(self, commit: str, ck: str) -> dict[str, Any]:
        k = (commit, ck)
        if k in self._ev:
            return self._ev[k]
        names = self.checkpoint_files(ck)
        subj, date, body = self.commit_message(commit)
        prompt = self.checkpoint_blob(ck, "0/prompt.txt") if "0/prompt.txt" in names else ""
        meta: dict[str, Any] = {}
        try:
            meta = json.loads(self.checkpoint_blob(ck, "0/metadata.json"))
        except Exception:
            pass
        self._ev[k] = dict(commit=commit[:10], date=date, subject=subj, body_chars=len(body), body=body[:1500], checkpoint=ck, agent=meta.get("agent"),
                           sessions=sum(1 for n in names if n.endswith("/full.jsonl")), prompt_chars=len(prompt), prompt=prompt[:800])
        return self._ev[k]


def resolve_issue(repo: Repo, issue: dict[str, Any], at_created: bool = False) -> dict[str, Any]:
    """One issue -> spans it names -> blamed commits -> checkpoint-linked evidence rows."""
    rev = repo.rev_at(issue["created_at"]) if at_created else "HEAD"
    files, syms = refs_from((issue.get("title") or "") + "\n" + (issue.get("body") or ""))
    spans: list[Span] = []
    for f, a, b in files:
        lf = repo.locate_file(rev, f)
        if lf and a:
            spans.append((lf, a, b or a, "file:line"))
    for s in syms:
        for f, a, b in repo.func_spans(rev, s):
            spans.append((f, a, b, "func:" + s))
    lines = 0
    linked = 0
    pairs: collections.Counter[tuple[str, str]] = collections.Counter()
    for f, a, b, _ in spans:
        for c in repo.blame(rev, f, a, b):
            lines += 1
            ids = [i for i in repo.commit_checkpoints.get(c, []) if repo.checkpoint_tree(i)]
            if ids:
                linked += 1
                for i in ids:
                    pairs[(c, i)] += 1
    ev = [dict(repo.evidence(c, i), lines=n) for (c, i), n in pairs.most_common(8)]
    return dict(number=issue["number"], title=issue["title"], state=issue["state"], state_reason=issue.get("state_reason"), labels=issue["labels"], rev=rev[:10],
                files_named=len(files), symbols_named=len(syms), spans=len(spans), span_list=[list(x) for x in spans], lines=lines, lines_linked=linked,
                checkpoints=len({i for _, i in pairs}), evidence=ev)


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    pos = [a for a in argv if not a.startswith("--")]
    if len(pos) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    repo_path, issues_path, out_path = pos
    only: set[int] | None = None
    for a in argv:
        if a.startswith("--only="):
            only = {int(x) for x in a[7:].split(",")}
    repo = Repo(repo_path)
    with open(issues_path) as fh:
        issues = json.load(fh)
    results = [resolve_issue(repo, it, "--at-created" in argv) for it in issues if not only or it["number"] in only]
    with open(out_path, "w") as fh:
        json.dump(results, fh, indent=1)
    sp = [r for r in results if r["spans"]]
    tr = [r for r in results if r["lines_linked"]]
    print(f"issues={len(results)} | code located={len(sp)} | traced to >=1 public checkpoint={len(tr)}")
    by: dict[str, list[int]] = collections.defaultdict(lambda: [0, 0, 0])
    for r in results:
        k = r["state"] + "/" + str(r["state_reason"])
        by[k][0] += 1
        by[k][1] += bool(r["spans"])
        by[k][2] += bool(r["lines_linked"])
    for k, v in sorted(by.items()):
        print(f"  {k}: issues={v[0]} located={v[1]} traced={v[2]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Intent evidence for the commits behind an issue's code.

For each evidence commit the intent text is taken in this order: commit message body, then the
checkpoint transcript (full.jsonl in the checkpoint ref), then the prompt. Excerpts are compact and
carry their source, so they fit an LLM prompt and can be quoted back exactly."""
import json
from dataclasses import asdict, dataclass
from typing import Any

from .resolve import Repo

SOURCE_ORDER = ("commit_message", "transcript", "prompt")
BODY_CHARS = 1500
TRANSCRIPT_CHARS = 2000
TURN_CHARS = 600
PROMPT_CHARS = 800
TOTAL_CHARS = 28000
MAX_SESSIONS = 3

Turn = tuple[str, str]  # role, text


@dataclass(frozen=True)
class Excerpt:
    source: str  # one of SOURCE_ORDER
    commit: str
    checkpoint: str
    text: str

    def to_dict(self) -> dict[str, str]:
        return asdict(self)


def transcript_turns(jsonl: str) -> list[Turn]:
    """What the human and the agent said, in order. Tool calls, tool results and harness events are dropped."""
    turns: list[Turn] = []
    for line in jsonl.splitlines():
        try:
            o = json.loads(line)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        msg = o.get("message") if isinstance(o.get("message"), dict) else o
        role = msg.get("role") or o.get("type")
        if role not in ("user", "assistant"):
            continue
        content = msg.get("content")
        parts: list[str] = []
        if isinstance(content, str):
            parts.append(content)
        elif isinstance(content, list):
            for b in content:
                if isinstance(b, dict) and b.get("type") in ("text", "thinking"):
                    parts.append(b.get("text") or b.get("thinking") or "")
        text = "\n".join(p.strip() for p in parts if p and p.strip())
        if text:
            turns.append((role, text))
    return turns


def focus_terms(span_list: list[list[Any]]) -> list[str]:
    """Symbols and file names the issue points at; used to pick the relevant transcript turns."""
    terms: list[str] = []
    for f, _a, _b, how in span_list:
        if how.startswith("func:"):
            terms.append(how[5:])
        terms.append(f.rsplit("/", 1)[-1])
    return list(dict.fromkeys(terms))


def _clip(text: str, limit: int, terms: list[str]) -> str:
    """Cut to `limit` chars, keeping the window around the first focus term. Always a verbatim slice."""
    if len(text) <= limit:
        return text
    hits = [i for i in (text.find(t) for t in terms) if i >= 0]
    start = max(0, min(hits) - limit // 3) if hits else 0
    start = min(start, len(text) - limit)
    return text[start:start + limit]


def select_turns(turns: list[Turn], terms: list[str], budget: int = TRANSCRIPT_CHARS, turn_chars: int = TURN_CHARS) -> str:
    """Turns that mention the most focus terms, within budget, in their original order.
    With no match, fall back to the first human turn and the last agent turn."""
    scored = [(sum(t in text for t in terms), i) for i, (_role, text) in enumerate(turns)]
    picked = [i for s, i in sorted(scored, key=lambda x: (-x[0], x[1])) if s > 0]
    if not picked and turns:
        first_user = next((i for i, (r, _) in enumerate(turns) if r == "user"), 0)
        last_agent = next((i for i in range(len(turns) - 1, -1, -1) if turns[i][0] == "assistant"), first_user)
        picked = list(dict.fromkeys([first_user, last_agent]))
    kept: list[tuple[int, str]] = []
    used = 0
    for i in picked:
        role, text = turns[i]
        piece = f"[{role}] {_clip(text, turn_chars, terms)}"
        if used + len(piece) > budget:
            break
        kept.append((i, piece))
        used += len(piece)
    return "\n".join(p for _, p in sorted(kept))


def intent_excerpts(commit: str, checkpoint: str, body: str, turns: list[Turn], prompt: str, terms: list[str]) -> list[Excerpt]:
    """Excerpts for one commit in SOURCE_ORDER. Empty sources are left out."""
    texts = {
        "commit_message": _clip(body.strip(), BODY_CHARS, terms),
        "transcript": select_turns(turns, terms),
        "prompt": prompt.strip()[:PROMPT_CHARS],
    }
    return [Excerpt(s, commit, checkpoint, texts[s]) for s in SOURCE_ORDER if texts[s]]


def collect(repo: Repo, resolved: dict[str, Any], total_chars: int = TOTAL_CHARS) -> list[Excerpt]:
    """Excerpts for every evidence row of a resolver result, most-blamed commit first, capped in total size."""
    terms = focus_terms(resolved["span_list"])
    commits = {c[:10]: c for c in repo.commit_checkpoints}
    out: list[Excerpt] = []
    used = 0
    for row in resolved["evidence"]:
        ck = row["checkpoint"]
        full = commits.get(row["commit"], row["commit"])
        subject, _date, body = repo.commit_message(full)
        names = repo.checkpoint_files(ck)
        sessions = sorted(n for n in names if n.endswith("/full.jsonl"))[:MAX_SESSIONS]
        turns = [t for n in sessions for t in transcript_turns(repo.checkpoint_blob(ck, n))]
        prompt = repo.checkpoint_blob(ck, "0/prompt.txt") if "0/prompt.txt" in names else ""
        message = subject + ("\n\n" + body if body else "")
        for ex in intent_excerpts(row["commit"], ck, message, turns, prompt, terms):
            if used + len(ex.text) > total_chars:
                return out
            out.append(ex)
            used += len(ex.text)
    return out


def render(excerpts: list[Excerpt]) -> str:
    """Excerpts as numbered blocks for an LLM prompt."""
    return "\n\n".join(
        f"<evidence id=\"{i}\" source=\"{e.source}\" commit=\"{e.commit}\" checkpoint=\"{e.checkpoint}\">\n{e.text}\n</evidence>"
        for i, e in enumerate(excerpts, 1)
    )

